{
    /// <summary>
    /// Changes the editable username of a business account; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetBusinessAccountUsernameAsync(string businessConnectionId = default, string username = default)
    {

           using var activity =  StartCallActivity("SetBusinessAccountUsernameAsync", typeof(SetBusinessAccountUsername).FullName ?? "SetBusinessAccountUsernameAsync");

           try
           {
             return client.SetBusinessAccountUsernameAsync(businessConnectionId, username);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
